import type { FC } from 'react';
import { useEffect, useRef } from 'react';

interface Particle {
  x: number;
  y: number;
  z: number; // depth: 0 = far, 1 = near — drives size, speed and parallax
  vx: number;
  vy: number;
  r: number;
}

const parseHsl = (value: string): [number, number, number] => {
  const [h, s, l] = value.trim().split(/\s+/).map((part) => parseFloat(part));
  return [h || 0, s || 0, l || 0];
};

/**
 * Ambient canvas backdrop for the homepage: a slowly drifting network of
 * depth-sorted "data nodes" with connecting lines and mouse parallax,
 * giving a lightweight pseudo-3D data-graph feel without a 3D library.
 */
const DataBackground: FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    const styles = getComputedStyle(document.documentElement);
    const [ah, as, al] = parseHsl(styles.getPropertyValue('--accent') || '162 55% 82%');
    const [gh, gs, gl] = parseHsl(styles.getPropertyValue('--accent-glow') || '168 85% 68%');

    let width = 0;
    let height = 0;
    let particles: Particle[] = [];
    let rafId = 0;
    let running = true;

    let mouseX = 0;
    let mouseY = 0;
    let targetMouseX = 0;
    let targetMouseY = 0;

    const BASE_COUNT = 60;

    const seedParticles = () => {
      const area = width * height;
      const scale = Math.min(1, area / (1280 * 720));
      const count = Math.max(20, Math.round(BASE_COUNT * scale));
      particles = Array.from({ length: count }, () => {
        const z = 0.15 + Math.random() * 0.85;
        return {
          x: Math.random() * width,
          y: Math.random() * height,
          z,
          vx: (Math.random() - 0.5) * 0.18 * z,
          vy: (Math.random() - 0.5) * 0.18 * z,
          r: 0.6 + z * 1.8,
        };
      });
    };

    const resize = () => {
      const rect = container.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      seedParticles();
    };

    const handleMouseMove = (e: MouseEvent) => {
      targetMouseX = (e.clientX - width / 2) / width;
      targetMouseY = (e.clientY - height / 2) / height;
    };

    const handleVisibility = () => {
      running = document.visibilityState === 'visible';
      if (running && !prefersReducedMotion) {
        cancelAnimationFrame(rafId);
        rafId = requestAnimationFrame(draw);
      }
    };

    const parallaxX = (p: Particle) => p.x + mouseX * 36 * (1 - p.z);
    const parallaxY = (p: Particle) => p.y + mouseY * 36 * (1 - p.z);

    const draw = () => {
      ctx.clearRect(0, 0, width, height);

      mouseX += (targetMouseX - mouseX) * 0.04;
      mouseY += (targetMouseY - mouseY) * 0.04;

      for (const p of particles) {
        p.x += p.vx;
        p.y += p.vy;
        if (p.x < -20) p.x = width + 20;
        if (p.x > width + 20) p.x = -20;
        if (p.y < -20) p.y = height + 20;
        if (p.y > height + 20) p.y = -20;
      }

      const linkDist = Math.min(width, height) * 0.22;
      ctx.lineWidth = 1;
      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        const px = parallaxX(p);
        const py = parallaxY(p);
        for (let j = i + 1; j < particles.length; j++) {
          const q = particles[j];
          const qx = parallaxX(q);
          const qy = parallaxY(q);
          const dx = px - qx;
          const dy = py - qy;
          const dist = Math.hypot(dx, dy);
          const threshold = linkDist * ((p.z + q.z) / 2 + 0.35);
          if (dist < threshold) {
            // Use the light accent (not the dark primary) so links read against a near-black background.
            const alpha = (1 - dist / threshold) * 0.5 * ((p.z + q.z) / 2 + 0.2);
            ctx.strokeStyle = `hsla(${ah}, ${as}%, ${al}%, ${alpha})`;
            ctx.beginPath();
            ctx.moveTo(px, py);
            ctx.lineTo(qx, qy);
            ctx.stroke();
          }
        }
      }

      for (const p of particles) {
        const px = parallaxX(p);
        const py = parallaxY(p);
        ctx.beginPath();
        ctx.arc(px, py, p.r, 0, Math.PI * 2);
        ctx.fillStyle = `hsla(${ah}, ${as}%, ${al}%, ${0.25 + p.z * 0.5})`;
        ctx.shadowColor = `hsla(${gh}, ${gs}%, ${gl}%, ${Math.min(1, p.z)})`;
        ctx.shadowBlur = p.z * 6;
        ctx.fill();
      }
      ctx.shadowBlur = 0;

      if (running) rafId = requestAnimationFrame(draw);
    };

    resize();
    window.addEventListener('resize', resize);
    window.addEventListener('mousemove', handleMouseMove, { passive: true });
    document.addEventListener('visibilitychange', handleVisibility);

    if (prefersReducedMotion) {
      // Render a single static frame — no motion, still shows the data-graph motif.
      draw();
    } else {
      rafId = requestAnimationFrame(draw);
    }

    return () => {
      running = false;
      cancelAnimationFrame(rafId);
      window.removeEventListener('resize', resize);
      window.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('visibilitychange', handleVisibility);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      aria-hidden="true"
      className="fixed inset-0 -z-10 overflow-hidden pointer-events-none"
    >
      <canvas ref={canvasRef} />
      {/* Soft vignette so the graph fades into the page edges instead of hard-cutting */}
      <div className="absolute inset-0 bg-gradient-to-b from-background/40 via-transparent to-background/60" />
    </div>
  );
};

export default DataBackground;
