import type { FC } from 'react';
import { useEffect, lazy, Suspense } from 'react';
import { BrowserRouter, Routes, Route, Outlet, useLocation } from "react-router-dom";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { AnimatePresence } from "framer-motion";
import Lenis from "lenis";
import { Toaster } from "@/components/ui/toaster";
import { Toaster as Sonner } from "@/components/ui/sonner";

// Pages (lazy-loaded so each route ships its own chunk)
const Index = lazy(() => import("./pages/Index"));
const Projects = lazy(() => import("./pages/Projects"));
const Experience = lazy(() => import("./pages/Experience"));
const Certifications = lazy(() => import("./pages/Certifications"));
const About = lazy(() => import("./pages/About"));
const ToolsIndex = lazy(() => import("./pages/tools/ToolsIndex"));
const ColorConverter = lazy(() => import("./pages/tools/ColorConverter"));
const QrGenerator = lazy(() => import("./pages/tools/QrGenerator"));
const ImageConverter = lazy(() => import("./pages/tools/ImageConverter"));
const PaletteCollection = lazy(() => import("./pages/tools/PaletteCollection"));
const ContrastChecker = lazy(() => import("./pages/tools/ContrastChecker"));
const PdfToJpg = lazy(() => import("./pages/tools/PdfToJpg"));
const ImageToPdf = lazy(() => import("./pages/tools/ImageToPdf"));
const CompressPdf = lazy(() => import("./pages/tools/CompressPdf"));
const ProtectPdf = lazy(() => import("./pages/tools/ProtectPdf"));
const UnlockPdf = lazy(() => import("./pages/tools/UnlockPdf"));
const QrGeneratorShare = lazy(() => import("./pages/tools/QrGeneratorShare"));
const ContrastCheckerShare = lazy(() => import("./pages/tools/ContrastCheckerShare"));
const NotFound = lazy(() => import("./pages/NotFound"));

// Components
import Navbar from "./components/Navbar";
import ScrollToTop from "./components/ScrollToTop";
import DataBackground from "./components/DataBackground";
import StandaloneToolsLayout from "./components/StandaloneToolsLayout";

const queryClient = new QueryClient();

// Chrome for every normal page: background, navbar, scroll-to-top. Shared
// result pages (below) render as siblings of this layout instead of inside
// it, so a link someone shares shows only the result — not the full site.
// isolate: scopes descendants' z-index (e.g. DataBackground's fixed, -z-10 canvas) to this
// subtree, so a negative z-index can't fall behind this div's own opaque background.
// No overflow-x-hidden here: it's already set on <body> (index.css), and duplicating it
// on this nested div makes the div its own CSS scroll container, which silently breaks
// position:sticky for every descendant (sticky computes against the nearest scroll
// container, not the real viewport, once one exists in the ancestor chain).
const SiteLayout: FC = () => (
  <div className="min-h-screen bg-background text-foreground isolate">
    <DataBackground />
    <Navbar />
    <main className="relative">
      <Outlet />
    </main>
    <ScrollToTop />
  </div>
);

const AppRoutes: FC = () => {
  const location = useLocation();

  return (
    <AnimatePresence mode="wait">
      <Suspense fallback={null}>
        <Routes location={location} key={location.pathname}>
          <Route element={<SiteLayout />}>
            <Route path="/" element={<Index />} />
            <Route path="/projects" element={<Projects />} />
            <Route path="/experience" element={<Experience />} />
            <Route path="/certifications" element={<Certifications />} />
            <Route path="/about" element={<About />} />
            <Route path="/tools" element={<ToolsIndex />} />
            <Route path="/tools/color-converter" element={<ColorConverter />} />
            <Route path="/tools/qr-generator" element={<QrGenerator />} />
            <Route path="/tools/image-converter" element={<ImageConverter />} />
            <Route path="/tools/palette-collection" element={<PaletteCollection />} />
            <Route path="/tools/contrast-checker" element={<ContrastChecker />} />
            <Route path="/tools/pdf-to-jpg" element={<PdfToJpg />} />
            <Route path="/tools/image-to-pdf" element={<ImageToPdf />} />
            <Route path="/tools/compress-pdf" element={<CompressPdf />} />
            <Route path="/tools/protect-pdf" element={<ProtectPdf />} />
            <Route path="/tools/unlock-pdf" element={<UnlockPdf />} />
            <Route path="*" element={<NotFound />} />
          </Route>

          {/* Standalone tools hub: same tool pages, no portfolio chrome —
              shareable on its own. See StandaloneToolsLayout and
              getToolsBasePath (data/tools.ts) for how tool-to-tool links
              stay inside /toolbox instead of falling back to /tools. */}
          <Route path="/toolbox" element={<StandaloneToolsLayout />}>
            <Route index element={<ToolsIndex />} />
            <Route path="color-converter" element={<ColorConverter />} />
            <Route path="qr-generator" element={<QrGenerator />} />
            <Route path="image-converter" element={<ImageConverter />} />
            <Route path="palette-collection" element={<PaletteCollection />} />
            <Route path="contrast-checker" element={<ContrastChecker />} />
            <Route path="pdf-to-jpg" element={<PdfToJpg />} />
            <Route path="image-to-pdf" element={<ImageToPdf />} />
            <Route path="compress-pdf" element={<CompressPdf />} />
            <Route path="protect-pdf" element={<ProtectPdf />} />
            <Route path="unlock-pdf" element={<UnlockPdf />} />
            <Route path="*" element={<NotFound />} />
          </Route>

          <Route path="/tools/qr-generator/share" element={<QrGeneratorShare />} />
          <Route path="/tools/contrast-checker/share" element={<ContrastCheckerShare />} />
        </Routes>
      </Suspense>
    </AnimatePresence>
  );
};

const useSmoothScroll = () => {
  useEffect(() => {
    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (prefersReducedMotion) return;

    const lenis = new Lenis({
      duration: 1.1,
      smoothWheel: true,
    });

    let rafId: number;
    const raf = (time: number) => {
      lenis.raf(time);
      rafId = requestAnimationFrame(raf);
    };
    rafId = requestAnimationFrame(raf);

    return () => {
      cancelAnimationFrame(rafId);
      lenis.destroy();
    };
  }, []);
};

const App: FC = () => {
  useSmoothScroll();

  return (
    <QueryClientProvider client={queryClient}>
      <Toaster />
      <Sonner />
      <BrowserRouter>
        <AppRoutes />
      </BrowserRouter>
    </QueryClientProvider>
  );
};

export default App;
