import type { FC } from 'react';
import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Menu, X } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';
import portfolioData from '../data/portfolio.json';

interface NavItem {
  path: string;
  label: string;
}

const navItems: NavItem[] = [
  { path: '/', label: 'Home' },
  { path: '/projects', label: 'Projects' },
  { path: '/experience', label: 'Experience' },
  { path: '/certifications', label: 'Certifications' },
  { path: '/tools', label: 'Tools' },
  { path: '/about', label: 'About' },
];

// Nested tool routes (/tools/color-converter, etc.) should still light up
// the "Tools" nav item, not just an exact match on /tools itself.
const isNavItemActive = (item: NavItem, pathname: string) =>
  pathname === item.path || (item.path !== '/' && pathname.startsWith(`${item.path}/`));

const Navbar: FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();

  const toggleMenu = () => setIsOpen(!isOpen);

  return (
    <motion.nav
      initial={{ opacity: 0, y: -16 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: 'easeOut' }}
      className="fixed top-0 left-0 right-0 z-50 bg-background/40 backdrop-blur-md"
    >
      <div className="section-container flex items-center justify-between py-3 md:py-4">
        <Link
          to="/"
          className="px-3 py-1.5 text-xl md:text-2xl font-display font-bold text-accent tracking-tight rounded-full hover:bg-accent/10 transition-colors"
        >
          {portfolioData.abbrName}
        </Link>

        {/* Desktop Navigation */}
        <div className="hidden md:flex items-center gap-7">
          {navItems.map((item) => {
            const isActive = isNavItemActive(item, location.pathname);
            return (
              <Link
                key={item.path}
                to={item.path}
                className={`relative py-2 text-base font-medium transition-colors duration-200 ${
                  isActive
                    ? "text-accent after:content-[''] after:absolute after:left-0 after:right-0 after:-bottom-0.5 after:h-0.5 after:rounded-full after:bg-accent"
                    : 'text-foreground/65 hover:text-foreground'
                }`}
              >
                {item.label}
              </Link>
            );
          })}
        </div>

        {/* Mobile Menu Button */}
        <button
          onClick={toggleMenu}
          className="md:hidden p-2 text-foreground/70 hover:text-accent transition-colors rounded-full"
          aria-label="Toggle menu"
          aria-expanded={isOpen}
        >
          {isOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Mobile Navigation */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.25, ease: 'easeOut' }}
            className="md:hidden overflow-hidden border-t border-border bg-background"
          >
            <div className="section-container flex flex-col gap-1 py-3">
              {navItems.map((item) => {
                const isActive = isNavItemActive(item, location.pathname);
                return (
                  <Link
                    key={item.path}
                    to={item.path}
                    onClick={() => setIsOpen(false)}
                    className={`px-1 py-3 text-base font-medium border-b transition-colors ${
                      isActive
                        ? 'text-accent border-accent'
                        : 'text-foreground/70 border-transparent hover:text-foreground'
                    }`}
                  >
                    {item.label}
                  </Link>
                );
              })}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.nav>
  );
};

export default Navbar;
