import type { FC } from 'react';
import { useEffect } from 'react';
import { Link, Outlet } from 'react-router-dom';
import portfolioData from '@/data/portfolio.json';
import DataBackground from '@/components/DataBackground';
import ScrollToTop from '@/components/ScrollToTop';

// Chrome for the standalone /toolbox experience: same tools, none of the
// portfolio's Navbar (no Home/Projects/Experience/Certifications/About), so
// this can be shared on its own as a free-tools site. A small credit at the
// bottom links back to the portfolio for anyone curious, but it's the only
// mention of it. Rendered as a sibling of SiteLayout in App.tsx, not nested
// under it — see the /toolbox route group.
const StandaloneToolsLayout: FC = () => {
  useEffect(() => {
    const previousTitle = document.title;
    document.title = `Free Online Tools | ${portfolioData.name}`;
    return () => {
      document.title = previousTitle;
    };
  }, []);

  return (
    <div className="min-h-screen bg-background text-foreground isolate flex flex-col">
      <DataBackground />

      {/* Fixed like the portfolio Navbar, so every tools page's built-in
          pt-24 (ToolLayout/ToolsIndex — sized to clear that Navbar) still
          clears this header correctly without each page knowing which
          layout it's rendered under. */}
      <header className="fixed top-0 left-0 right-0 z-50 bg-background/40 backdrop-blur-md">
        <div className="section-container py-5">
          <Link
            to="/toolbox"
            className="inline-block px-3 py-1.5 -mx-3 text-xl md:text-2xl font-display font-bold text-accent tracking-tight rounded-full hover:bg-accent/10 transition-colors"
          >
            Tools
          </Link>
        </div>
      </header>

      <main className="relative flex-1">
        <Outlet />
      </main>

      <footer className="section-container py-8 flex justify-center text-sm text-muted-foreground">
        <span>
          Made by{' '}
          <Link to="/" className="font-medium text-accent hover:underline">
            {portfolioData.name}
          </Link>
        </span>
      </footer>

      <ScrollToTop />
    </div>
  );
};

export default StandaloneToolsLayout;
